class Solution {
public:
    int totalDistance(string s) {
        string rows[] = {"qwertyuiop", "asdfghjkl", "zxcvbnm"};
        int row[26] = {}, col[26] = {};
        for (int r = 0; r < 3; ++r)
            for (int c = 0; c < (int)rows[r].size(); ++c) {
                int id = rows[r][c] - 'a';
                row[id] = r; col[id] = c;
            }
        int prev = 0, ans = 0; // 'a'
        for (char ch : s) {
            int cur = ch - 'a';
            ans += abs(row[cur] - row[prev]) + abs(col[cur] - col[prev]);
            prev = cur;
        }
        return ans;
    }
};
